// SPDX-License-Identifier: MPL-2.0
// Checks src/d2svg/{geo,label,shape} against the path data and label/icon
// anchors the pinned Go D2 v0.9.0 renderer wrote into every non-sketch e2e
// golden SVG. Included as a unit-test module from src/d2svg/shape.rs.
//
// Fixture: tests/fixtures/d2svg-geometry/golden.json (oracle tier), regenerated by
// recipe d2svg-geometry-golden (scripts/d2svg-geometry-fixtures.py --golden) from
// ../d2/e2etests/testdata/**/{board.exp.json,sketch.exp.svg}. The script
// records, per shape group (class = base64url(EscapeText(id))), the `d`
// attributes of shapes d2svg draws from lib/shape path data, the first
// `<text x y>` of plain-text labels and `<image x y w h>` of icons, and the
// first `<text x y>` of labelled connections. Shapes with nothing to check
// are omitted; every exclusion below is counted and printed.

use super::super::geo::{self, Point};
use super::super::label::{self, Position};
use super::super::shape::{self, Shape};
use super::super::svgtext::format_float;
use serde_json::Value;
use std::collections::BTreeMap;

fn fixture() -> Value {
    serde_json::from_str(d2_rs_testdata::oracle_fixture!("tests/fixtures/d2svg-geometry/golden.json")).expect("json")
}

fn num(v: &Value, key: &str) -> f64 {
    v.get(key).and_then(Value::as_f64).unwrap_or(0.0)
}

fn flag(v: &Value, key: &str) -> bool {
    v.get(key).and_then(Value::as_bool).unwrap_or(false)
}

fn text<'a>(v: &'a Value, key: &str) -> &'a str {
    v.get(key).and_then(Value::as_str).unwrap_or("")
}

/// d2target.GetIconSize (test helper; d2target is ported elsewhere).
fn get_icon_size(b: &geo::Box, position: &str) -> i64 {
    const DEFAULT_ICON_SIZE: i64 = 32;
    const MAX_ICON_SIZE: i64 = 64;
    let icon_position = Position::from_string(position);
    let min_dimension = geo::go_min(b.width, b.height) as i64;
    let half_min_dimension = (0.5 * min_dimension as f64).ceil() as i64;
    let mut size = if icon_position == Position::InsideMiddleCenter {
        half_min_dimension
    } else {
        min_dimension.min(DEFAULT_ICON_SIZE.max(half_min_dimension))
    };
    size = size.min(MAX_ICON_SIZE);
    if !icon_position.is_outside() {
        let pad = label::PADDING as i64;
        size = size.min(
            ((b.width as i64) - 2 * pad)
                .max(0)
                .min(((b.height as i64) - 2 * pad).max(0)),
        );
    }
    size
}

/// Goldens last regenerated before the pinned source's renderer changes, so
/// no faithful port of the pinned code can reproduce them byte for byte:
/// txtar/c4-theme/* were written at d2 e9aee89a1 (2025-03-13), before
/// 1b7d74b30 (2025-08-01) made chopPrecision map -0 to 0 and before text
/// coordinates were serialized with svg.FormatFloat (they still carry Go
/// `%f` spellings such as "732.500000"). The pinned Go code, run on the same
/// c4-person box (1089,0,415,394), prints "M 1297 0 ...", as the port does.
/// A mismatch on these boards is accepted only when the golden value shows
/// one of those two stale spellings; it is still counted and printed.
const STALE_GOLDEN_BOARDS: &[&str] = &["txtar/c4-theme/dagre", "txtar/c4-theme/elk"];

fn has_stale_spelling(golden: &str) -> bool {
    let percent_f = golden
        .split(|c: char| !(c.is_ascii_digit() || c == '.' || c == '-'))
        .any(|tok| tok.split_once('.').is_some_and(|(_, frac)| frac.len() == 6));
    let negative_zero = golden.split(' ').any(|tok| tok == "-0");
    percent_f || negative_zero
}

#[derive(Default)]
struct Tally {
    matched: usize,
    total: usize,
    skipped: BTreeMap<String, usize>,
    mismatches: Vec<String>,
    stale: Vec<String>,
}

impl Tally {
    fn skip(&mut self, reason: &str) {
        *self.skipped.entry(reason.to_owned()).or_default() += 1;
    }

    fn check(&mut self, ok: bool, board: &str, golden: &str, msg: impl FnOnce() -> String) {
        self.total += 1;
        if ok {
            self.matched += 1;
        } else if STALE_GOLDEN_BOARDS.contains(&board) && has_stale_spelling(golden) {
            self.stale.push(msg());
        } else {
            self.mismatches.push(msg());
        }
    }

    fn report(&self, name: &str) {
        eprintln!(
            "{name}: {}/{} matched, {} stale-golden, {} mismatched; skipped {:?}",
            self.matched,
            self.total,
            self.stale.len(),
            self.mismatches.len(),
            self.skipped
        );
        for m in self.stale.iter().take(3) {
            eprintln!("  STALE {m}");
        }
        for m in self.mismatches.iter().take(30) {
            eprintln!("  MISMATCH {m}");
        }
    }
}

#[test]
fn golden_shape_paths_labels_and_icons() {
    let fx = fixture();
    let mut paths = Tally::default();
    let mut labels = Tally::default();
    let mut icons = Tally::default();
    let mut conns = Tally::default();

    for board in fx["boards"].as_array().unwrap() {
        let board_name = text(board, "board");
        for s in board["shapes"].as_array().unwrap() {
            let id = text(s, "id");
            let dsl = text(s, "t");
            if flag(s, "nf") {
                paths.skip(
                    "shape group not found in svg (old-format golden, e.g. d2Version v0.6.0-HEAD)",
                );
                continue;
            }
            let shape_type = shape::dsl_shape_to_shape_type(dsl);
            let tl = Point::new(num(s, "x"), num(s, "y"));
            let (w, h) = (num(s, "w"), num(s, "h"));
            let mut sh = shape::new_shape(shape_type, geo::Box::new(tl, w, h));
            if shape_type == shape::CLOUD_TYPE {
                if let Some(ar) = s.get("ar").and_then(Value::as_f64) {
                    sh.set_inner_box_aspect_ratio(ar);
                }
            }
            let multiple = flag(s, "m");
            let three_dee = flag(s, "td");

            // ---- path data (drawShape default/hexagon branches)
            if let Some(found) = s.get("d").and_then(Value::as_array) {
                let found: Vec<&str> = found.iter().filter_map(Value::as_str).collect();
                if dsl == "hexagon" && three_dee {
                    paths.skip("3d hexagon (render3DHexagon, not lib/shape)");
                } else {
                    let mut expected = Vec::new();
                    if multiple {
                        let multiple_tl = tl.add_vector(&geo::Vector::new(&[10.0, -10.0]));
                        expected.extend(
                            shape::new_shape(shape_type, geo::Box::new(multiple_tl, w, h))
                                .get_svg_path_data(),
                        );
                    }
                    expected.extend(sh.get_svg_path_data());
                    // The rendered group lists the expected paths in order
                    // (fill-pattern overlays may follow).
                    let mut cursor = 0;
                    for e in &expected {
                        let pos = found[cursor..].iter().position(|d| d == e);
                        let all_found = found.join(" | ");
                        paths.check(pos.is_some(), board_name, &all_found, || {
                            format!("{board_name} {id} ({dsl}) path {e:?} not in {found:?}")
                        });
                        if let Some(p) = pos {
                            cursor += p + 1;
                        }
                    }
                }
            }

            // ---- plain label anchor
            if let Some(tx) = s.get("tx").and_then(Value::as_array) {
                let op = s.get("op").and_then(Value::as_f64).unwrap_or(1.0);
                if matches!(dsl, "class" | "sql_table") {
                    labels.skip("class/sql_table header (drawClass/drawTable)");
                } else if op == 0.0 {
                    labels.skip("opacity 0");
                } else if let Some(first) = tx.first().and_then(Value::as_array) {
                    let position = Position::from_string(text(s, "lp"));
                    let b = if position.is_outside() || position.is_border() {
                        let mut b = sh.get_box();
                        if three_dee {
                            let offset_y = if dsl == "hexagon" { 15 / 2 } else { 15 } as f64;
                            b.top_left.y -= offset_y;
                            b.height += offset_y;
                            b.width += 15.0;
                        } else if multiple {
                            b.top_left.y -= 10.0;
                            b.height += 10.0;
                            b.width += 10.0;
                        }
                        b
                    } else {
                        sh.get_inner_box()
                    };
                    let (lw, lh, fs) = (num(s, "lw"), num(s, "lh"), num(s, "fs"));
                    let label_tl = position.get_point_on_box(&b, label::PADDING, lw, lh);
                    let x = format_float(label_tl.x + lw / 2.0);
                    let y = format_float(label_tl.y + fs);
                    let (gx, gy) = (first[0].as_str().unwrap(), first[1].as_str().unwrap());
                    labels.check(
                        x == gx && y == gy,
                        board_name,
                        &format!("{gx} {gy}"),
                        || {
                            format!(
                                "{board_name} {id} ({dsl} {}) label got ({x},{y}) want ({gx},{gy})",
                                text(s, "lp")
                            )
                        },
                    );
                }
            }

            // ---- icon
            if let Some(im) = s.get("im").and_then(Value::as_array) {
                let op = s.get("op").and_then(Value::as_f64).unwrap_or(1.0);
                if dsl == "image" {
                    icons.skip("image shape (own <image>)");
                } else if op == 0.0 {
                    icons.skip("opacity 0");
                } else if let Some(first) = im.first().and_then(Value::as_array) {
                    let icon_position = Position::from_string(text(s, "ip"));
                    let b = if icon_position.is_outside() {
                        sh.get_box()
                    } else {
                        sh.get_inner_box()
                    };
                    let size = get_icon_size(&b, text(s, "ip"));
                    let itl = icon_position.get_point_on_box(
                        &b,
                        label::PADDING,
                        size as f64,
                        size as f64,
                    );
                    let got = (format_float(itl.x), format_float(itl.y), size.to_string());
                    let want = (
                        first[0].as_str().unwrap().to_owned(),
                        first[1].as_str().unwrap().to_owned(),
                        first[2].as_str().unwrap().to_owned(),
                    );
                    let golden = format!("{} {}", want.0, want.1);
                    icons.check(got == want, board_name, &golden, || {
                        format!("{board_name} {id} ({dsl}) icon got {got:?} want {want:?}")
                    });
                }
            }
        }

        for c in board["connections"].as_array().unwrap() {
            let id = text(c, "id");
            if flag(c, "nf") {
                conns.skip("connection group not found in svg");
                continue;
            }
            let Some(first) = c
                .get("tx")
                .and_then(Value::as_array)
                .and_then(|t| t.first())
                .and_then(Value::as_array)
            else {
                conns.skip("no plain-text label anchor");
                continue;
            };
            let route: Vec<Point> = c["r"]
                .as_array()
                .unwrap()
                .iter()
                .map(|p| Point::new(p[0].as_f64().unwrap(), p[1].as_f64().unwrap()))
                .collect();
            if route.len() < 2 {
                conns.skip("route shorter than 2 points");
                continue;
            }
            let position = Position::from_string(text(c, "lp"));
            let (lw, lh, fs) = (num(c, "lw"), num(c, "lh"), num(c, "fs"));
            let Some((label_tl, _)) =
                position.try_get_point_on_route(&route, num(c, "sw"), num(c, "lpc"), lw, lh)
            else {
                conns.skip("non-edge label position (nil label point)");
                continue;
            };
            let x = format_float(label_tl.x + lw / 2.0);
            let y = format_float(label_tl.y + fs);
            let (gx, gy) = (first[0].as_str().unwrap(), first[1].as_str().unwrap());
            conns.check(
                x == gx && y == gy,
                board_name,
                &format!("{gx} {gy}"),
                || {
                    format!(
                        "{board_name} {id} ({}) label got ({x},{y}) want ({gx},{gy})",
                        text(c, "lp")
                    )
                },
            );
        }
    }

    paths.report("shape paths");
    labels.report("shape labels");
    icons.report("shape icons");
    conns.report("connection labels");
    let total_mismatches = paths.mismatches.len()
        + labels.mismatches.len()
        + icons.mismatches.len()
        + conns.mismatches.len();
    assert!(
        paths.total > 0 && labels.total > 0 && conns.total > 0,
        "empty golden inventory"
    );
    assert_eq!(
        total_mismatches, 0,
        "golden geometry mismatches (see stderr)"
    );
}
